appVersion.zeropsYamlJson:
{
		"build": {
			"base": [
				"ubuntu@24.04"
			],
			"deployFiles": [
				"./"
			],
			"cache": null
		},
		"deploy": {
			"readinessCheck": {
				"exec": {
					"command": "/var/www/sim check"
				},
				"FailureTimeout": 60000000000,
				"RetryPeriod": 10000000000
			},
			"temporaryShutdown": true
		},
		"run": {
			"prepareCommands": [
				"sudo apt-get update \u0026\u0026 sudo apt-get install -y jq",
				"echo revision1 | sudo tee /opt/example-prepare"
			],
			"base": "ubuntu@24.04",
			"start": "./sim",
			"volume": {
				"hostname": "membervolume",
				"mountPath": "/mnt/membervolume",
				"readOnly": false
			},
			"envVariables": {
				"EXAMPLE_CP": "no",
				"EXAMPLE_OVERRIDE": "yaml-wins",
				"EXAMPLE_VOLUME": "/mnt/membervolume"
			}
		}
	}
